window.products.push({"id":974144,"name":"The Potters, LTD Brie Baker, Vintage Denim","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/716zx4Z4asL._AC_SL1500_.jpg","description":"The Potters, LTD is the work of Iowans Karen and Stephen Steininger who create functional and affordable pottery that makes everyday tasks a little brighter. Many of their pieces are embellished with geometric patterns using the traditional technique of slip trailing. The patterns vary as they respond to the inspiration of the moment, making each piece a unique creation. For gifting or keeping, The Potters, LTD pottery is sure to be used and enjoyed for years to come.","images":["https://m.media-amazon.com/images/I/716zx4Z4asL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"The Potters, LTD","source_asin":"B07536SQ2N","category_path":"Home & Kitchen"},"sku":"BM-974144","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B07536SQ2N","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B07536SQ2N","price_pending":true,"merchant_ready":false});
