window.products.push({"id":974266,"name":"LJ Home Fashions Tania Faux Silk Vintage Floral Grommet Curtain Panels (Set of 2), 54x95-in, Silver Grey/Black","category":"homeandappliances","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/A1Xm785CrAL._AC_SL1500_.jpg","description":"Add a vintage look to your decor with Tania curtains by LJ Home Fashions. Design inspired by the classic '60s era. Faux embroidered floral design give Tania curtains a unique and elegant look. Available in four (4) colors - silver grey/black, charcoal grey/chartreuse green,ocean blue/white and taupe/red. Faux silk has a soft sheen and subtle texture. 100% polyester. Perfect combination of design, color and 100% privacy curtains. Set includes TWO (2) grommet top curtains. Each curtain is 54x95 inches. 1.6-in grommet diameter. Dry cleaning recommended","images":["https://m.media-amazon.com/images/I/A1Xm785CrAL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"LJ Home Fashions","source_asin":"B00PC74SW2","category_path":"Home & Kitchen"},"sku":"BM-974266","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00PC74SW2","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00PC74SW2","price_pending":true,"merchant_ready":false});
